contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We accept an amount to forward as Ether to c.go. The test contract must hold at least that much.
    function run(uint amount) public payable {
        require(address(this).balance >= amount);

        // record balance of this contract before the call
        uint before = address(this).balance;

        // perform the call and capture whether it reverted
        bool reverted;
        try c.go{value: amount}() {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint after = address(this).balance;

        // General rule: if call reverted, this contract's balance must be unchanged; if it succeeded, balance must be before - amount
        // (Because when c.go succeeds it forwards amount to the external target and then transfers any remaining balance in c to c.owner — none goes back to this contract.)
        assert(reverted ? (after == before) : (after == before - amount));
    }

    receive() external payable {}
}

