contract InvMutTest {
    C c;
    address initialOwner;

    constructor(C _c) {
        c = _c;
        initialOwner = c.owner();
    }

    // send 'amount' wei to c.go; this contract must hold at least that much
    function run(uint amount) public payable {
        require(address(this).balance >= amount);

        // record balances before
        uint cBalBefore = address(c).balance;
        uint myBalBefore = address(this).balance;

        bool reverted;
        try c.go{value: amount}() {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint cBalAfter = address(c).balance;
        uint myBalAfter = address(this).balance;
        address ownerAfter = c.owner();

        // General rule:
        // - If call reverted: no requirements on balances except owner unchanged
        // - If call succeeded: c.balance must be zero, owner must equal initialOwner,
        //   and this test contract must not have gained Ether (it may have lost 'amount' or not, depending on external call),
        //   so myBalAfter <= myBalBefore.
        assert(reverted ? (ownerAfter == initialOwner) : (cBalAfter == 0 && ownerAfter == initialOwner && myBalAfter <= myBalBefore));
    }

    receive() external payable {}
}

